class Solution {
public:
    int wordsTyping(vector<string>& sentence, int rows, int cols) {
        string s = "";
        for (const string& w : sentence) s += w + " ";
        int n = s.size();
        int start = 0;
        for (int r = 0; r < rows; ++r) {
            start += cols;
            if (s[start % n] == ' ') {
                start++;
            } else {
                while (start > 0 && s[(start - 1) % n] != ' ') {
                    start--;
                }
            }
        }
        return start / n;
    }
};

class Solution {
    public int wordsTyping(String[] sentence, int rows, int cols) {
        StringBuilder sb = new StringBuilder();
        for (String w : sentence) sb.append(w).append(" ");
        String s = sb.toString();
        int n = s.length();
        int start = 0;
        for (int r = 0; r < rows; r++) {
            start += cols;
            if (s.charAt(start % n) == ' ') {
                start++;
            } else {
                while (start > 0 && s.charAt((start - 1) % n) != ' ') {
                    start--;
                }
            }
        }
        return start / n;
    }
}

/**
 * @param {string[]} sentence
 * @param {number} rows
 * @param {number} cols
 * @return {number}
 */
var wordsTyping = function(sentence, rows, cols) {
    const s = sentence.join(' ') + ' ';
    const n = s.length;
    let start = 0;
    for (let r = 0; r < rows; r++) {
        start += cols;
        if (s[start % n] === ' ') {
            start++;
        } else {
            while (start > 0 && s[(start - 1) % n] !== ' ') {
                start--;
            }
        }
    }
    return Math.floor(start / n);
};
